function selectDebtPaymentMethod(btn) {
    document.querySelectorAll('.btn-payment-method').forEach(b => b.classList.remove('selected'));
    btn.classList.add('selected');
    document.getElementById('debt-payment-method').value = btn.dataset.method;
    updateDebtSurchargeLabels();
}

function handleDebtPayment(e) {
    e.preventDefault();
    const amount = parseFloat(document.getElementById('debt-amount').value);
    const id = document.getElementById('debt-client-id').value;
    const paymentMethod = document.getElementById('debt-payment-method').value;

    const todayStr = new Date().toLocaleDateString();
    if (isDayClosed(todayStr)) {
        alert('El día ya está CERRADO. Reabrí el cierre para poder registrar pagos en esta fecha.');
        return;
    }

    if (!amount || amount <= 0) {
        alert('Monto inválido');
        return;
    }

    const index = clients.findIndex(c => c.id == id);
    if (index === -1) return;

    const surchargePct = getSurchargePercent(paymentMethod);
    const surchargeAmount = getSurchargeAmount(amount, paymentMethod);
    const totalWithSurcharge = amount + surchargeAmount;

    const methodLabels = { cash: 'EFECTIVO', transfer: 'TRANSFERENCIA', mercadopago: 'MERCADO PAGO', tarjeta: 'TARJETA' };
    const methodName = methodLabels[paymentMethod] || paymentMethod.toUpperCase();

    let confirmMsg = `💰 Monto a pagar: ${formatMoney(amount)}`;
    confirmMsg += `\n👤 Cliente: ${clients[index].name}`;
    confirmMsg += `\n💳 Método: ${methodName}`;
    if (surchargePct > 0) {
        confirmMsg += `\n📈 Recargo (${surchargePct}%): ${formatMoney(surchargeAmount)}`;
        confirmMsg += `\n💵 Total con recargo: ${formatMoney(totalWithSurcharge)}`;
    }

    if (!confirm(confirmMsg + '\n\n¿Confirmar pago de deuda?')) return;

    // Allocate payment across unpaid credit sales
    const unpaidCredits = getUnpaidCredits(clients[index].id);
    let remaining = amount;
    const paidCreditSaleIds = [];
    const paymentAllocations = {};

    unpaidCredits.sort((a, b) => a.id - b.id);
    for (const credit of unpaidCredits) {
        if (remaining <= 0) break;
        const creditRemaining = (credit.total || 0) - (credit.paidAmount || 0);
        if (creditRemaining <= 0) continue;
        const allocated = Math.min(remaining, creditRemaining);
        paymentAllocations[credit.id] = (paymentAllocations[credit.id] || 0) + allocated;
        remaining -= allocated;
        paidCreditSaleIds.push(credit.id);
        credit.paidAmount = (credit.paidAmount || 0) + allocated;
        if (credit.paidAmount >= (credit.total || 0)) {
            credit.status = 'paid';
        }
    }

    clients[index].debt = Math.max(0, (clients[index].debt || 0) - amount);
    saveClients();
    saveSales();

    const paymentRecord = {
        id: Date.now(),
        date: new Date().toLocaleDateString(),
        time: new Date().toLocaleTimeString(),
        items: [{ name: 'Pago de deuda', qty: 1, price: amount }],
        total: totalWithSurcharge,
        subtotal: amount,
        surchargePct: surchargePct,
        surchargeAmount: surchargeAmount,
        clientId: clients[index].id,
        clientName: clients[index].name,
        paymentMethod: paymentMethod,
        isDebtPayment: true,
        debtMethodLabel: methodName,
        paidCreditSaleIds: paidCreditSaleIds,
        paymentAllocations: paymentAllocations
    };

    sales.unshift(paymentRecord);
    saveSales();

    updateStats();
    renderSalesHistory();
    closeModal('pay-debt-modal');
    renderClients();
    renderClientSelect();
    alert('Pago registrado correctamente.');
}

function checkAndPayDebt() {
    const clientId = document.getElementById('pos-client-select').value;
    if (!clientId) {
        alert('Por favor, selecciona un cliente primero.');
        return;
    }
    openPayDebtModal(parseInt(clientId));
}

function checkAndDeleteClient() {
    const clientId = document.getElementById('pos-client-select').value;
    if (!clientId) {
        alert('Por favor, selecciona un cliente primero para eliminar.');
        return;
    }
    deleteClient(parseInt(clientId));
}

// --- Client History & WhatsApp ---
function getPaidAmountForCreditSale(saleId) {
    let totalPaid = 0;
    sales.forEach(s => {
        if (s.isDebtPayment && s.paidCreditSaleIds && s.paidCreditSaleIds.includes(saleId)) {
            totalPaid += (s.paymentAllocations && s.paymentAllocations[saleId]) || 0;
        }
    });
    return totalPaid;
}

function showClientHistory(clientId, showAll) {
    clientHistoryCurrentId = clientId;
    const client = clients.find(c => c.id == clientId);
    if (!client) return;

    const titleEl = document.getElementById('client-history-title');
    const contentEl = document.getElementById('client-history-content');
    const whatsappBtn = document.getElementById('btn-send-whatsapp');

    titleEl.innerText = `Historial de Fiado - ${client.name}`;

    const creditSales = sales.filter(s => s.clientId == clientId && s.paymentMethod === 'credit');
    const debtPayments = sales.filter(s => s.clientId == clientId && s.isDebtPayment);

    const combined = [
        ...creditSales.map(s => ({ ...s, _type: 'credit' })),
        ...debtPayments.map(s => ({ ...s, _type: 'payment' }))
    ].sort((a, b) => {
        const dateA = (a.date || '') + ' ' + (a.time || '');
        const dateB = (b.date || '') + ' ' + (b.time || '');
        return dateA.localeCompare(dateB);
    });

    const filtered = showAll ? combined : combined.filter(item => {
        if (item._type === 'payment') return true;
        return item.status !== 'paid';
    });

    if (filtered.length === 0) {
        contentEl.innerHTML = `<div class="client-history-empty">No hay movimientos registrados para este cliente.</div>`;
    } else {
        let html = '';
        filtered.forEach(item => {
            if (item._type === 'credit') {
                const paidAmount = getPaidAmountForCreditSale(item.id);
                const remaining = (item.total || 0) - paidAmount;
                const statusLabel = item.status === 'paid'
                    ? ' <span style="color:#10b981;">✓ PAGADO</span>'
                    : ` <span style="color:#fbbf24;">Pend: ${formatMoney(Math.max(0, remaining))}</span>`;
                const itemsText = (item.items || []).map(i => `${i.qty}x ${i.name}`).join(', ');
                html += `
                    <div class="client-history-sale" style="border-left: 3px solid #8b5cf6;">
                        <div class="meta">
                            <span>${item.date || ''} ${item.time || ''} - Compra${statusLabel}</span>
                            <span>${formatMoney(item.total || 0)}</span>
                        </div>
                        <div class="items">${itemsText || '-'}</div>
                    </div>
                `;
            } else {
                const pm = item.debtMethodLabel || item.paymentMethod.toUpperCase();
                const paidTo = (item.paidCreditSaleIds && item.paidCreditSaleIds.length > 0)
                    ? ` - Afectó ${item.paidCreditSaleIds.length} venta(s)`
                    : '';
                const surchargeInfo = (item.surchargePct && item.surchargePct > 0)
                    ? ` (Rec: ${item.surchargePct}%)`
                    : '';
                html += `
                    <div class="client-history-sale" style="border-left: 3px solid #10b981;">
                        <div class="meta">
                            <span>${item.date || ''} ${item.time || ''} - Pago${surchargeInfo}</span>
                            <span style="display:flex;flex-direction:column;align-items:flex-end;gap:2px;">
                                <span>${formatMoney(item.total || 0)}</span>
                                <span style="font-size:0.7rem;color:#10b981;font-weight:600;">${pm}</span>
                            </span>
                        </div>
                        <div class="items" style="color: #10b981;">${pm}${paidTo}</div>
                    </div>
                `;
            }
        });
        const currentDebt = client.debt || 0;
        html += `<div class="client-history-total"><span>Deuda Actual</span><span>${formatMoney(currentDebt)}</span></div>`;
        contentEl.innerHTML = html;
    }

    const toggleBtn = document.getElementById('btn-toggle-history');
    if (toggleBtn) {
        toggleBtn.innerText = showAll ? 'Ocultar pagados' : 'Mostrar todo';
        toggleBtn.onclick = () => showClientHistory(clientId, !showAll);
    }

    if (client.phone && client.phone.trim()) {
        whatsappBtn.style.display = 'flex';
    } else {
        whatsappBtn.style.display = 'none';
    }

    openModal('client-history-modal');
}

function sendWhatsAppSummary(clientId) {
    const id = clientId || clientHistoryCurrentId;
    const client = clients.find(c => c.id == id);
    if (!client) return;

    let phone = (client.phone || '').replace(/[^0-9]/g, '');
    if (!phone) {
        alert('El cliente no tiene un número de teléfono cargado.');
        return;
    }
    if (!phone.startsWith('54')) {
        phone = '54' + phone;
    }

    const allCredits = sales.filter(s => s.clientId == id && s.paymentMethod === 'credit');
    const debtPayments = sales.filter(s => s.clientId == id && s.isDebtPayment);
    const currentDebt = client.debt || 0;

    let message = `🧾 *Resumen de Cuenta - ${client.name}*\n`;
    message += `━━━━━━━━━━━━━━━\n`;
    message += `📅 *Fecha:* ${new Date().toLocaleDateString()}\n\n`;
    message += `*Movimientos:*\n`;

    const combined = [
        ...allCredits.map(s => ({ ...s, _type: 'credit' })),
        ...debtPayments.map(s => ({ ...s, _type: 'payment' }))
    ].sort((a, b) => {
        const dateA = (a.date || '') + ' ' + (a.time || '');
        const dateB = (b.date || '') + ' ' + (b.time || '');
        return dateA.localeCompare(dateB);
    });

    if (combined.length === 0) {
        message += `No hay movimientos registrados.\n`;
    } else {
        combined.forEach(item => {
            if (item._type === 'credit') {
                const paidAmount = getPaidAmountForCreditSale(item.id);
                const remaining = (item.total || 0) - paidAmount;
                const status = item.status === 'paid' ? '✓' : `Pend: ${formatMoney(Math.max(0, remaining))}`;
                const itemsText = (item.items || []).map(i => `${i.qty}x ${i.name}`).join(', ');
                message += `🛒 ${item.date || ''} - ${formatMoney(item.total || 0)} - ${itemsText || '-'} (${status})\n`;
            } else {
                const pm = item.debtMethodLabel || item.paymentMethod.toUpperCase();
                const surchargeInfo = (item.surchargePct && item.surchargePct > 0)
                    ? ` (Rec: ${item.surchargePct}%)`
                    : '';
                message += `💳 ${item.date || ''} - ${formatMoney(item.total || 0)} - ${pm}${surchargeInfo}\n`;
            }
        });
    }

    message += `\n━━━━━━━━━━━━━━━\n`;
    message += `💰 *Deuda Actual:* ${formatMoney(currentDebt)}\n`;
    message += `━━━━━━━━━━━━━━━\n`;
    message += `\nGracias por su confianza 🙌`;

    const waUrl = `https://api.whatsapp.com/send?phone=${phone}&text=${encodeURIComponent(message)}`;
    window.open(waUrl, '_blank');
}

// --- Sales Logic ---
function renderSalesHistory() {
    const tbody = document.getElementById('sales-list');
    tbody.innerHTML = '';

    sales.forEach(s => {
        const badgeMap = {
            cash: { cls: 'badge-cash', text: 'EFECTIVO' },
            transfer: { cls: 'badge-transfer', text: 'TRANSFERENCIA' },
            credit: { cls: 'badge-credit', text: 'CREDITO' },
            mercadopago: { cls: 'badge-mercadopago', text: 'M. PAGO' },
            tarjeta: { cls: 'badge-tarjeta', text: 'TARJETA' }
        };
        const b = s.isDebtPayment
            ? { cls: badgeMap[s.paymentMethod]?.cls || 'badge-cash', text: 'PAGO DEUDA' }
            : badgeMap[s.paymentMethod] || { cls: 'badge-cash', text: s.paymentMethod };
        const badgeClass = b.cls;
        const badgeText = b.text;
        const tr = document.createElement('tr');
        const surchargeInfo = (s.surchargePct && s.surchargePct > 0)
            ? `<br><small style="color: #fbbf24;">Rec: ${s.surchargePct}% ($${(s.surchargeAmount || 0).toFixed(2)})</small>`
            : '';
        tr.innerHTML = `
            <td>#${s.id}</td>
            <td>${s.date}</td>
            <td>${s.time}</td>
            <td>$${s.total.toFixed(2)}</td>
            <td>${s.clientName || 'Consumidor Final'}</td>
            <td><span class="badge ${badgeClass}">${badgeText}</span></td>
            <td>
                <div style="display:flex; justify-content:space-between; align-items:center">
                    <small>${s.items.map(i => `${i.qty}x ${i.name}`).join(', ')}${surchargeInfo}</small>
                    <button class="btn-small" onclick="printTicket(${s.id})" title="Imprimir Ticket">
                        <i class="fa-solid fa-print"></i>
                    </button>
                </div>
            </td>
        `;
        tbody.appendChild(tr);
    });
    updateStats();
}

function updateStats() {
    // Filter sales for today
    const today = new Date().toLocaleDateString();
    const todaysSales = sales.filter(s => s.date === today);

    const count = todaysSales.length;
    const income = todaysSales.reduce((sum, s) => sum + s.total, 0);

    const countEl = document.getElementById('sales-today-count');
    const incomeEl = document.getElementById('income-today-display');

    if (countEl) countEl.innerText = count;
    if (incomeEl) incomeEl.innerText = `$${income.toFixed(2)}`;
}

