// --- Import / Export Logic ---
function exportData(type) {
    if (sales.length === 0) {
        alert('No hay ventas para exportar');
        return;
    }

    const dataCopy = sales.map(s => ({
        ID: s.id,
        Fecha: s.date,
        Hora: s.time,
        Items: s.items.map(i => `${i.qty}x ${i.name}`).join(', '),
        Total: s.total
    }));

    if (type === 'json') {
        const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(sales, null, 2));
        const downloadAnchorNode = document.createElement('a');
        downloadAnchorNode.setAttribute("href", dataStr);
        downloadAnchorNode.setAttribute("download", "ventas_delacocinaalasador.json");
        document.body.appendChild(downloadAnchorNode);
        downloadAnchorNode.click();
        downloadAnchorNode.remove();
    } else if (type === 'excel') {
        if (typeof XLSX === 'undefined') { alert('Librería Excel no cargada'); return; }
        const ws = XLSX.utils.json_to_sheet(dataCopy);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, "Ventas");
        XLSX.writeFile(wb, "ventas_delacocinaalasador.xlsx");
    }
}

function importData(input) {
    const file = input.files[0];
    if (!file) return;

    const reader = new FileReader();

    if (file.name.endsWith('.json')) {
        reader.onload = function (e) {
            try {
                const importedSales = JSON.parse(e.target.result);
                mergeSales(importedSales);
            } catch (err) {
                alert('Error al leer JSON');
                console.error(err);
            }
        };
        reader.readAsText(file);
    } else if (file.name.endsWith('.xlsx') || file.name.endsWith('.xls')) {
        reader.onload = function (e) {
            try {
                const data = new Uint8Array(e.target.result);
                const workbook = XLSX.read(data, { type: 'array' });
                const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
                const jsonData = XLSX.utils.sheet_to_json(firstSheet);

                // Map Excel columns back to App structure
                const mappedSales = jsonData.map(row => {
                    // Reconstruct items from string "1x A, 2x B"
                    let parsedItems = [];
                    if (row.Items && typeof row.Items === 'string') {
                        parsedItems = row.Items.split(', ').map(itemStr => {
                            const parts = itemStr.split('x '); // Try splitting by 'x '
                            if (parts.length >= 2) {
                                // parts[0] is qty, parts[1] (and others if name has x) is name
                                return {
                                    qty: parseInt(parts[0]) || 1,
                                    name: parts.slice(1).join('x '), // Join back if name had 'x '
                                    price: 0 // Price per item is lost in this simple format, setting 0
                                };
                            }
                            return { qty: 1, name: itemStr, price: 0 };
                        });
                    }

                    return {
                        id: row.ID || Date.now(),
                        date: row.Fecha || new Date().toLocaleDateString(),
                        time: row.Hora || '00:00:00',
                        total: row.Total || 0,
                        items: parsedItems
                    };
                });

                mergeSales(mappedSales);
            } catch (err) {
                alert('Error al leer Excel');
                console.error(err);
            }
        };
        reader.readAsArrayBuffer(file);
    }

    input.value = '';
}

// --- Full Backup / Restore ---
function exportFullBackup() {
    const backup = {
        _version: 1,
        _app: 'DelaCocinaalAsador',
        _exportedAt: new Date().toISOString(),
        products: products,
        sales: sales,
        clients: clients,
        cashClosures: cashClosures,
        surchargeConfig: surchargeConfig
    };

    const dateStr = new Date().toISOString().slice(0, 10);
    const dataStr = 'data:text/json;charset=utf-8,' + encodeURIComponent(JSON.stringify(backup, null, 2));
    const a = document.createElement('a');
    a.setAttribute('href', dataStr);
    a.setAttribute('download', `backup_completo_${dateStr}.json`);
    document.body.appendChild(a);
    a.click();
    a.remove();
}

let _pendingRestoreData = null;

function importFullBackup(input) {
    const file = input.files[0];
    if (!file) return;
    input.value = '';

    const reader = new FileReader();
    reader.onload = function (e) {
        try {
            const data = JSON.parse(e.target.result);

            // Validate it's a full backup
            if (!data._app || data._app !== 'DelaCocinaalAsador') {
                alert('❌ El archivo no es un backup válido de esta aplicación.\n\nAsegurate de usar un archivo generado por "Backup Completo".');
                return;
            }

            _pendingRestoreData = data;
            document.getElementById('restore-filename').innerText = file.name;

            const confirmBtn = document.getElementById('btn-confirm-restore');
            confirmBtn.onclick = function () {
                applyFullRestore(_pendingRestoreData);
                closeModal('restore-confirm-modal');
            };

            openModal('restore-confirm-modal');
        } catch (err) {
            alert('❌ Error al leer el archivo de backup. Verificá que sea un JSON válido.');
            console.error(err);
        }
    };
    reader.readAsText(file);
}

function applyFullRestore(data) {
    if (Array.isArray(data.products))     { products = data.products;           localStorage.setItem('kiosco_products',       JSON.stringify(products)); }
    if (Array.isArray(data.sales))        { sales = data.sales;                 localStorage.setItem('kiosco_sales',          JSON.stringify(sales)); }
    if (Array.isArray(data.clients))      { clients = data.clients;             localStorage.setItem('kiosco_clients',        JSON.stringify(clients)); }
    if (Array.isArray(data.cashClosures)) { cashClosures = data.cashClosures;   localStorage.setItem('kiosco_cash_closures',  JSON.stringify(cashClosures)); }
    if (data.surchargeConfig && typeof data.surchargeConfig === 'object') {
        surchargeConfig = data.surchargeConfig;
        localStorage.setItem('kiosco_surcharge_config', JSON.stringify(surchargeConfig));
    }

    // Refresh all views
    renderProducts('all');
    renderInventory();
    renderSalesHistory();
    renderClients();
    renderClientSelect();
    renderCashClosure();
    updateStats();
    updateSurchargeLabels();

    alert('✅ Backup restaurado correctamente.\n\nTodos los datos han sido recuperados.');
}

function mergeSales(importedSales) {
    let count = 0;
    if (!Array.isArray(importedSales)) { alert('Formato inválido'); return; }

    importedSales.forEach(impSale => {
        if (!sales.find(s => s.id === impSale.id)) {
            sales.push(impSale);
            count++;
        }
    });

    // Sort descending
    sales.sort((a, b) => b.id - a.id);
    saveSales();
    renderSalesHistory();
    alert(`Se importaron ${count} ventas nuevas.`);
}

// --- Ticket Printing ---
function printTicket(saleId) {
    const sale = sales.find(s => s.id === saleId);
    if (!sale) return;

    const ticketMethodMap = {
        cash: 'EFECTIVO',
        transfer: 'TRANSFERENCIA',
        credit: '** A CUENTA / FIADO **',
        mercadopago: 'MERCADO PAGO',
        tarjeta: 'TARJETA'
    };
    const methodLabel = sale.isDebtPayment
        ? `PAGO DEUDA (${ticketMethodMap[sale.paymentMethod] || ''})`
        : ticketMethodMap[sale.paymentMethod] || '';

    const itemsHtml = sale.items.map(item =>
        `<div class="item"><span>${item.qty} ${item.name}</span><span>$${(item.price * item.qty).toFixed(2)}</span></div>`
    ).join('');

    const surchargeHtml = (sale.surchargePct && sale.surchargePct > 0)
        ? `<div class="item"><span>Recargo (${sale.surchargePct}%)</span><span>$${(sale.surchargeAmount || 0).toFixed(2)}</span></div>`
        : '';

    const ticketHtml = `
        <html><head><title>Ticket de Venta</title>
        <style>
            body { font-family: "Courier New", monospace; width: 280px; margin: 0 auto; padding: 10px; color: #000; background: #fff; }
            .header { text-align: center; margin-bottom: 20px; border-bottom: 1px dashed #000; padding-bottom: 10px; }
            .item { display: flex; justify-content: space-between; margin-bottom: 5px; font-size: 0.9em; }
            .total { border-top: 1px dashed #000; padding-top: 10px; margin-top: 10px; font-weight: bold; text-align: right; }
            .footer { text-align: center; margin-top: 20px; font-size: 0.8em; }
        </style></head><body>
        <div class="header">
            <h3>De la cocina al asador</h3>
            <p>${sale.date} - ${sale.time}</p>
            <p>Ticket #${sale.id}</p>
            <p>Cliente: ${sale.clientName || 'Consumidor Final'}</p>
            ${methodLabel ? `<p><strong>${methodLabel}</strong></p>` : ''}
        </div>
        ${itemsHtml}
        ${surchargeHtml}
        <div class="total">TOTAL: $${sale.total.toFixed(2)}</div>
        <div class="footer">Gracias por su compra!</div>
    </body></html>`;

    // Usar iframe oculto para evitar bloqueo de popups (tablets, móviles, etc.)
    const iframe = document.getElementById('print-frame');
    if (iframe) {
        iframe.parentNode.removeChild(iframe);
    }
    const frame = document.createElement('iframe');
    frame.id = 'print-frame';
    frame.style.position = 'absolute';
    frame.style.top = '-9999px';
    frame.style.left = '-9999px';
    frame.style.width = '0';
    frame.style.height = '0';
    document.body.appendChild(frame);

    frame.contentDocument.open();
    frame.contentDocument.write(ticketHtml);
    frame.contentDocument.close();

    setTimeout(() => {
        try {
            frame.contentWindow.print();
        } catch (e) {
            alert('No se pudo imprimir. Verificá que haya una impresora configurada.');
        }
    }, 500);
}

// --- Weight Sale (Balanza) Logic ---
function openWeightModal(product) {
    document.getElementById('weight-sale-form').reset();
    document.getElementById('weight-total-preview').innerText = '0.00';

    const nameField = document.getElementById('weight-prod-name');
    const priceField = document.getElementById('weight-price-kg');
    const titleEl = document.getElementById('weight-modal-title');
    const prodIdField = document.getElementById('weight-prod-id');

    if (product) {
        // Modo producto precargado (desde la grilla)
        prodIdField.value = product.id;
        nameField.value = product.name;
        nameField.readOnly = true;
        nameField.className = 'weight-field-readonly';
        priceField.value = product.pricePerKg || 0;
        priceField.readOnly = true;
        priceField.className = 'weight-field-readonly';
        titleEl.textContent = 'Vender por Peso — ' + product.name;
    } else {
        // Modo manual (desde botón "Peso")
        prodIdField.value = '';
        nameField.readOnly = false;
        nameField.className = '';
        nameField.focus();
        priceField.readOnly = false;
        priceField.className = '';
        titleEl.textContent = 'Venta por Peso';
    }

    openModal('weight-sale-modal');
    // Si hay balanza activa y producto precargado, enfocar campo peso
    if (product) {
        document.getElementById('weight-kg').focus();
    }
}

function previewWeightTotal() {
    const kg = parseFloat(document.getElementById('weight-kg').value) || 0;
    const priceKg = parseFloat(document.getElementById('weight-price-kg').value) || 0;
    document.getElementById('weight-total-preview').innerText = (kg * priceKg).toFixed(2);
}

document.addEventListener('input', function (e) {
    if (e.target.id === 'weight-kg' || e.target.id === 'weight-price-kg') {
        previewWeightTotal();
    }
});

function handleWeightSale(e) {
    e.preventDefault();
    const name = document.getElementById('weight-prod-name').value.trim();
    const kg = parseFloat(document.getElementById('weight-kg').value) || 0;
    const priceKg = parseFloat(document.getElementById('weight-price-kg').value) || 0;
    const prodId = document.getElementById('weight-prod-id').value;
    const total = kg * priceKg;

    if (!name || kg <= 0 || priceKg <= 0) {
        alert('Completa todos los campos correctamente.');
        return;
    }

    const weightItem = {
        id: prodId ? parseFloat(prodId) : Date.now() + Math.random(),
        name: `${name} (${kg.toFixed(3)} kg x $${priceKg.toFixed(2)})`,
        price: total,
        qty: 1,
        isWeightItem: true
    };

    cart.push(weightItem);
    renderCart();
    closeModal('weight-sale-modal');
}

// --- Quick Sale (Venta Rápida / Personalizada) ---
function openQuickSaleModal() {
    document.getElementById('quick-sale-form').reset();
    document.getElementById('quick-sale-concept').focus();
    openModal('quick-sale-modal');
}

function handleQuickSale(e) {
    e.preventDefault();
    const concept = document.getElementById('quick-sale-concept').value.trim();
    const amount = parseFloat(document.getElementById('quick-sale-amount').value);

    if (!concept || !amount || amount <= 0) {
        alert('Completa todos los campos correctamente.');
        return;
    }

    const quickItem = {
        id: Date.now() + Math.random(),
        name: `${concept} (venta rápida)`,
        price: amount,
        qty: 1,
        isQuickSale: true
    };

    cart.push(quickItem);
    renderCart();
    closeModal('quick-sale-modal');
}

// --- Mobile Cart Logic ---
function toggleCartMobile() {
    const cartPanel = document.getElementById('cart-panel');
    cartPanel.classList.toggle('open');
}
